<?php require __DIR__.'/app/bootstrap.php';if(user()){header('Location:/');exit;}$error='';$email=strtolower(trim($_POST['email']??''));if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();$pass=$u&&password_verify($_POST['password']??'',$u['password_hash']);if($pass){if((int)($u['two_factor_enabled']??0)===1){$_SESSION['2fa_pending_uid']=$u['id'];$_SESSION['2fa_pending_email']=$email;header('Location:/two-factor.php');exit;}session_regenerate_id(true);$_SESSION['uid']=$u['id'];security_log_login((int)$u['id'],$email,true);security_touch_session((int)$u['id']);try{link_existing_ptero_user_for_local_user($u);}catch(Throwable $e){}db()->prepare('UPDATE users SET last_login_at=NOW(),last_login_ip=? WHERE id=?')->execute([$_SERVER['REMOTE_ADDR']??null,$u['id']]);header('Location:/');exit;}security_log_login($u?(int)$u['id']:null,$email,false);$error='Invalid email or password.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>FoxNetwork Login</title><link rel="stylesheet" href="/assets/portal.css?v=9"></head><body><div class="auth"><form class="authbox" method="post"><img src="/images/logo.png"><h1>Welcome back.</h1><p class="muted">Sign in to FoxNetwork Control Center.</p><?php if($error):?><div class="error"><?=e($error)?></div><?php endif?><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="field"><label>Email</label><input type="email" name="email" required value="<?=e($email)?>"></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn primary wide">Sign in</button><p><a class="link" href="/forgot-password.php">Forgot password?</a></p></form></div></body></html>
